buildTree:function(e,t,a,n){if(n>13)return[];var o=n+1,i=this.findInTree(e,a);if(i!=[]&&i.length>0)for(var s=0;s<i.length;s++){let a=i[s];var r={Master:a.Master,AgentID:a.AgentID,Login:a.Login,AgentType:a.AgentType,children:[]};"M"==a.AgentType&&this.buildTree(e,r.children,a.AgentID,o),t.push(r)}return t}